// ---- Shared: extra preferences stored in "Payload brut" (no new Airtable columns needed) ----
function lirePreferences(payloadBrut) {
  let b = {};
  try { b = JSON.parse(payloadBrut || '{}'); } catch (e) { b = {}; }
  const liste = function (x) { return Array.isArray(x) ? x.map(function (s) { return String(s).trim(); }).filter(Boolean) : []; };

  const CUISINES_SPOON = {
    'african':'African','africain':'African','american':'American','américain':'American','americain':'American',
    'british':'British','anglais':'British','cajun':'Cajun','caribbean':'Caribbean','caribéen':'Caribbean','antillais':'Caribbean',
    'chinese':'Chinese','chinois':'Chinese','eastern european':'Eastern European','european':'European','européen':'European',
    'french':'French','français':'French','german':'German','allemand':'German','greek':'Greek','grec':'Greek',
    'indian':'Indian','indien':'Indian','irish':'Irish','irlandais':'Irish','italian':'Italian','italien':'Italian',
    'japanese':'Japanese','japonais':'Japanese','jewish':'Jewish','korean':'Korean','coréen':'Korean','coreen':'Korean',
    'latin american':'Latin American','mediterranean':'Mediterranean','méditerranéen':'Mediterranean','mediterraneen':'Mediterranean',
    'mexican':'Mexican','mexicain':'Mexican','middle eastern':'Middle Eastern','nordic':'Nordic','scandinave':'Nordic',
    'southern':'Southern','spanish':'Spanish','espagnol':'Spanish','thai':'Thai','thaï':'Thai',
    'vietnamese':'Vietnamese','vietnamien':'Vietnamese','asian':'Asian','asiatique':'Asian'
  };
  const cuisinesSpoon = [], cuisinesLibres = [];
  liste(b.cuisines_extra).forEach(function (c) {
    const k = CUISINES_SPOON[c.toLowerCase()];
    if (k) cuisinesSpoon.push(k); else cuisinesLibres.push(c);
  });

  const INTOL = ['dairy','egg','gluten','grain','peanut','seafood','sesame','shellfish','soy','sulfite','tree nut','wheat'];
  const allergies = liste(b.allergies).filter(function (a) { return INTOL.indexOf(a) !== -1; });
  const allergiesAutres = liste(b.allergies_extra);
  const eviter = liste(b.exclude);
  const tempsMax = Number(b.max_time) || 0;
  const restes = !!b.leftovers;
  const lang = b.lang === 'fr' ? 'fr' : 'en';
  const nutrition = b.nutrition || 'balanced';
  const niveau = b.level || 'comfortable';
  const equipement = Array.isArray(b.equipment) ? b.equipment : ['oven', 'hob'];
  const sansFour = equipement.indexOf('oven') === -1 && equipement.indexOf('air_fryer') === -1;
  const sansPlaque = equipement.indexOf('hob') === -1;
  const lunchbox = !!b.lunchbox;
  const sansViande = Math.max(0, Math.min(7, Number(b.meat_free) || 0));
  const frigo = !!b.fridge_first;

  const params = [].concat(
    allergies.length ? ['intolerances=' + encodeURIComponent(allergies.join(','))] : [],
    (eviter.length || allergiesAutres.length) ? ['excludeIngredients=' + encodeURIComponent(eviter.concat(allergiesAutres).join(','))] : [],
    tempsMax ? ['maxReadyTime=' + tempsMax] : [],
    nutrition === 'protein' ? ['minProtein=25'] : [],
    nutrition === 'light' ? ['maxCalories=550'] : [],
    (sansFour || sansPlaque) ? ['addRecipeInstructions=true'] : []
  );

  const outils = { oven: 'an oven', hob: 'a hob', microwave: 'a microwave', air_fryer: 'an air fryer', blender: 'a blender',
    food_processor: 'a food processor', slow_cooker: 'a slow cooker', pressure_cooker: 'a pressure cooker', rice_cooker: 'a rice cooker', grill: 'a grill or barbecue' };
  const equipAutres = liste(b.equipment_extra);
  const lignes = [].concat(
    (allergies.length || allergiesAutres.length) ? ['- ALLERGIES, never include: ' + allergies.concat(allergiesAutres).join(', ')] : [],
    eviter.length ? ['- Foods the user does not eat: ' + eviter.join(', ')] : [],
    tempsMax ? ['- Maximum cooking time: ' + tempsMax + ' minutes'] : [],
    cuisinesLibres.length ? ['- Also enjoys these cuisines: ' + cuisinesLibres.join(', ')] : [],
    nutrition === 'protein' ? ['- Nutrition focus: high protein, favour recipes with the most protein.'] : [],
    nutrition === 'light' ? ['- Nutrition focus: lighter meals, favour lower-calorie recipes.'] : [],
    niveau === 'beginner' ? ['- The cook is a BEGINNER: pick simple recipes with few ingredients and basic techniques, nothing technical.'] : [],
    niveau === 'confident' ? ['- The cook is confident: more elaborate recipes are welcome.'] : [],
    ['- Kitchen equipment available: ' + (equipement.map(function (e) { return outils[e]; }).filter(Boolean).concat(equipAutres).join(', ') || 'very basic') + ', plus basic tools (knives, bowls). Never pick a recipe that needs equipment not in this list.'],
    equipement.some(function (e) { return ['slow_cooker', 'pressure_cooker', 'rice_cooker'].indexOf(e) !== -1; }) ? ['- Recipes that make good use of their slow cooker, pressure cooker or rice cooker are a plus.'] : [],
    equipement.indexOf('air_fryer') !== -1 ? ['- Air fryer available: air-fryer friendly recipes are a plus.'] : [],
    lunchbox ? ['- Lunches are eaten away from home: lunch dishes must travel well in a lunch box and taste good cold or reheated in a microwave.'] : [],
    sansViande ? ['- Make ' + sansViande + ' day(s) of the week fully meat-free (no meat, no fish), spread across the week.'] : [],
    frigo ? ['- USE UP THE PANTRY: build the week around the pantry ingredients, the recipes using the most of them come first.'] : [],
    lang === 'fr' ? ['- Language: write every titre (the dish name, translated naturally) and every pourquoi in French.'] : []
  );

  return {
    cuisinesSpoon: cuisinesSpoon, restes: restes, lang: lang, frigo: frigo, sansFour: sansFour, sansPlaque: sansPlaque,
    params: params, lignesPrompt: lignes
  };
}

// ⚠️ COLLE TA CLÉ SPOONACULAR ICI
const SPOONACULAR_KEY = 'YOUR_SPOONACULAR_API_KEY';

const demande = $('Validate Form').first().json;
const recordId = $('Save Request').first().json.id;

// Traduction des valeurs du site vers le vocabulaire Spoonacular
const regimes = {
  'aucun': '',
  'vegetarien': 'vegetarian',
  'vegan': 'vegan',
  'sans_gluten': 'gluten free',
  'sans_lactose': 'dairy free'
};
const cuisinesMap = {
  'italien': 'Italian',
  'asiatique': 'Asian',
  'francais': 'French',
  'mexicain': 'Mexican',
  'moyen_orient': 'Middle Eastern',
  'indien': 'Indian'
};

const prefs = lirePreferences(demande['Payload brut']);

const cuisines = (demande.Cuisines || [])
  .map(function (c) { return cuisinesMap[c]; })
  .filter(Boolean)
  .concat(prefs.cuisinesSpoon)
  .filter(function (c, i, a) { return a.indexOf(c) === i; })
  .join(',');

const parts = [
  'apiKey=' + encodeURIComponent(SPOONACULAR_KEY),
  prefs.frigo ? 'number=50' : 'number=30',
  'addRecipeInformation=true',
  'fillIngredients=true',
  'addRecipeNutrition=true',
  'sort=popularity'
];

const regime = regimes[demande.Regime] || '';
if (regime) { parts.push('diet=' + encodeURIComponent(regime)); }
if (cuisines) { parts.push('cuisine=' + encodeURIComponent(cuisines)); }
prefs.params.forEach(function (p) { parts.push(p); });

return [{
  json: {
    url: 'https://api.spoonacular.com/recipes/complexSearch?' + parts.join('&'),
    reference: demande.Reference,
    recordId: recordId,
    creneaux: (demande.Creneaux || '').split(',').map(function (s) { return s.trim(); }).filter(Boolean),
    budget: demande.Budget,
    personnes: demande.Personnes,
    regime: demande.Regime,
    notes: demande.Notes || '',
    stock: demande.Stock || '',
    lignesPrefs: prefs.lignesPrompt,
    restes: prefs.restes,
    lang: prefs.lang,
    frigo: prefs.frigo,
    sansFour: prefs.sansFour,
    sansPlaque: prefs.sansPlaque
  }
}];

// ---- Shared: turn Spoonacular results into our recipe pool (quantities scaled, nutrition per person) ----
function construirePool(recettes, personnes) {
  return recettes.map(function (r) {
    const facteur = personnes / (Number(r.servings) || personnes);
    const nutr = ((r.nutrition || {}).nutrients || []);
    const val = function (nom) { const n = nutr.find(function (x) { return x.name === nom; }); return n ? Math.round(n.amount) : null; };
    const outils = [];
    (r.analyzedInstructions || []).forEach(function (a) { (a.steps || []).forEach(function (s) { (s.equipment || []).forEach(function (e) { outils.push(String(e.name || '').toLowerCase()); }); }); });
    return {
      id: r.id, titre: r.title, temps_min: r.readyInMinutes,
      lien: r.sourceUrl || ('https://spoonacular.com/recipes/' + r.id),
      calories: val('Calories'), proteines: val('Protein'), outils: outils,
      ingredients: (r.extendedIngredients || []).map(function (i) {
        const m = (i.measures && i.measures.metric) ? i.measures.metric : null;
        return { nom: i.nameClean || i.name, quantite: Math.round((Number(m ? m.amount : i.amount) || 0) * facteur * 100) / 100, unite: m ? (m.unitShort || m.unitLong || '') : (i.unit || '') };
      })
    };
  });
}

// ---- Shared: equipment filter + "use up my fridge" ranking ----
function affinerPool(pool, o, besoin) {
  let p = pool;
  const FOUR = /oven|baking sheet|baking pan|baking dish|roasting|casserole dish|muffin|loaf pan/;
  const PLAQUE = /frying pan|skillet|pot|saucepan|wok|stove|grill pan|dutch oven/;
  const filtre = p.filter(function (r) {
    return !r.outils.some(function (x) { return (o.sansFour && FOUR.test(x)) || (o.sansPlaque && PLAQUE.test(x)); });
  });
  if (filtre.length >= Math.max(besoin, 3)) p = filtre; // keep enough candidates, the prompt still forbids the rest
  const stock = String(o.stock || '').toLowerCase().split(',').map(function (s) { return s.trim(); }).filter(Boolean);
  p = p.map(function (r) {
    const noms = r.ingredients.map(function (i) { return String(i.nom).toLowerCase(); });
    const utilise = stock.filter(function (s) { return noms.some(function (n) { return n.indexOf(s) !== -1 || s.indexOf(n) !== -1; }); });
    return Object.assign({}, r, { utilise: utilise });
  });
  if (o.frigo) p.sort(function (a, b) { return b.utilise.length - a.utilise.length; });
  return p.slice(0, 30);
}

// ---- Shared: leftovers logic ----
const JOURS_ORDRE = ['Lun', 'Mar', 'Mer', 'Jeu', 'Ven', 'Sam', 'Dim'];
function diner_veille(c) { const p = c.split('_'); const i = JOURS_ORDRE.indexOf(p[0]); return i > 0 ? JOURS_ORDRE[i - 1] + '_soir' : null; }
function dejeuner_lendemain(c) { const p = c.split('_'); const i = JOURS_ORDRE.indexOf(p[0]); return i >= 0 && i < 6 ? JOURS_ORDRE[i + 1] + '_midi' : null; }
function estReste(c, restes, tous) { return !!restes && /_midi$/.test(c) && tous.indexOf(diner_veille(c)) !== -1; }
function nourritReste(c, restes, tous) { return !!restes && /_soir$/.test(c) && tous.indexOf(dejeuner_lendemain(c)) !== -1; }

// Builds the compact prompt for the cooking slots only (leftover lunches are copied later).
function construirePrompt(o) {
  const cuisson = o.aRemplir.filter(function (c) { return !estReste(c, o.restes, o.creneauxDemande); });
  const doubles = cuisson.filter(function (c) { return nourritReste(c, o.restes, o.creneauxDemande); });
  const lignes = o.pool.map(function (r) {
    return r.id + ' | ' + r.titre + ' | ' + r.temps_min + ' min | ' + (r.proteines ? r.proteines + ' g protein | ' : '') +
      r.ingredients.map(function (i) { return i.nom; }).join(', ') + (o.frigo && r.utilise && r.utilise.length ? ' | uses pantry: ' + r.utilise.join(', ') : '');
  });
  const ex = { creneau: cuisson[0] || 'Lun_soir', recette_id: o.pool[0].id };
  if (o.lang === 'fr') ex.titre = 'Nom du plat en français';
  ex.pourquoi = o.lang === 'fr' ? 'Une phrase courte.' : 'One short sentence.';
  ex.cout_estime = 6.5;
  const prompt = [o.intro,
    "- Budget for the whole week: " + o.budget + " euros for " + o.personnes + " people",
    "- Diet: " + o.regime,
    o.notes ? "- Also take into account: " + o.notes : "",
    o.stock ? "- Already in the pantry (prefer recipes using these): " + o.stock : ""
  ].concat(o.lignesPrefs || []).concat([
    o.gardes && o.gardes.length ? "- Meals already kept this week (avoid similar dishes): " + o.gardes.join('; ') : "",
    doubles.length ? "- These dinners are cooked in double to become the next day's lunch, so pick dishes that keep and reheat well (stews, curries, bakes, grain salads): " + doubles.join(', ') : "",
    "",
    "Slots to fill (exactly one recipe each): " + cuisson.join(', '),
    "",
    "Candidate recipes (id | title | time | protein per serving | ingredients). Use ONLY these ids:",
    lignes.join('\n'),
    "",
    "Rules: never repeat a recipe; vary dish types and proteins; reuse ingredients across meals to save money; longer recipes on evenings/weekend; cout_estime is the cost in euros of that meal for " + o.personnes + " people (one serving each).",
    "JSON format (one entry per slot in \"repas\", pourquoi max 15 words):",
    JSON.stringify({ repas: [ex] })
  ]).filter(Boolean).join('\n');
  return {
    cuisson: cuisson,
    corpsLLM: {
      model: 'openai/gpt-oss-120b', max_tokens: 6000, reasoning_effort: 'low', temperature: 0.4,
      response_format: { type: 'json_object' },
      messages: [
        { role: 'system', content: 'You are a meal-planning assistant. You always answer with a single valid JSON object and nothing else.' },
        { role: 'user', content: prompt }
      ]
    }
  };
}

const ctx = $('Build Search').first().json;
const rep = $input.first().json;
const statut = rep.statusCode;
const corps = rep.body || {};
function echec(raison) { return [{ json: { echec: true, raison: raison, recordId: ctx.recordId } }]; }
if (statut === 402) return echec("Quota Spoonacular épuisé pour aujourd'hui");
if (statut !== 200) return echec('Spoonacular a répondu ' + statut);
const recettes = corps.results || [];
if (recettes.length === 0) return echec('Aucune recette trouvée pour ces critères');

const personnes = Number(ctx.personnes) || 1;
const pool = affinerPool(construirePool(recettes, personnes), ctx, ctx.creneaux.length);
if (pool.length < Math.min(3, ctx.creneaux.length)) {
  return echec('Trop peu de recettes correspondent à tes critères (' + pool.length + '). Assouplis un filtre : temps de cuisine, nutrition, équipement ou allergies.');
}
const p = construirePrompt({
  intro: "Compose a weekly meal plan. Answer ONLY with a JSON object.\nConstraints:",
  aRemplir: ctx.creneaux, creneauxDemande: ctx.creneaux, restes: ctx.restes, lang: ctx.lang, frigo: ctx.frigo,
  pool: pool, budget: ctx.budget, personnes: personnes, regime: ctx.regime,
  notes: ctx.notes, stock: ctx.stock, lignesPrefs: ctx.lignesPrefs
});
return [{ json: {
  echec: false, recordId: ctx.recordId, reference: ctx.reference, run: 1, lang: ctx.lang,
  creneauxDemande: ctx.creneaux, aRemplir: ctx.creneaux, cuisson: p.cuisson,
  restes: !!ctx.restes, dinersGardes: {}, pool: pool, corpsLLM: p.corpsLLM
} }];

const ctx = $('Build Prompt').first().json;

// ---- Shared: turn Spoonacular results into our recipe pool (quantities scaled, nutrition per person) ----
function construirePool(recettes, personnes) {
  return recettes.map(function (r) {
    const facteur = personnes / (Number(r.servings) || personnes);
    const nutr = ((r.nutrition || {}).nutrients || []);
    const val = function (nom) { const n = nutr.find(function (x) { return x.name === nom; }); return n ? Math.round(n.amount) : null; };
    const outils = [];
    (r.analyzedInstructions || []).forEach(function (a) { (a.steps || []).forEach(function (s) { (s.equipment || []).forEach(function (e) { outils.push(String(e.name || '').toLowerCase()); }); }); });
    return {
      id: r.id, titre: r.title, temps_min: r.readyInMinutes,
      lien: r.sourceUrl || ('https://spoonacular.com/recipes/' + r.id),
      calories: val('Calories'), proteines: val('Protein'), outils: outils,
      ingredients: (r.extendedIngredients || []).map(function (i) {
        const m = (i.measures && i.measures.metric) ? i.measures.metric : null;
        return { nom: i.nameClean || i.name, quantite: Math.round((Number(m ? m.amount : i.amount) || 0) * facteur * 100) / 100, unite: m ? (m.unitShort || m.unitLong || '') : (i.unit || '') };
      })
    };
  });
}

// ---- Shared: equipment filter + "use up my fridge" ranking ----
function affinerPool(pool, o, besoin) {
  let p = pool;
  const FOUR = /oven|baking sheet|baking pan|baking dish|roasting|casserole dish|muffin|loaf pan/;
  const PLAQUE = /frying pan|skillet|pot|saucepan|wok|stove|grill pan|dutch oven/;
  const filtre = p.filter(function (r) {
    return !r.outils.some(function (x) { return (o.sansFour && FOUR.test(x)) || (o.sansPlaque && PLAQUE.test(x)); });
  });
  if (filtre.length >= Math.max(besoin, 3)) p = filtre; // keep enough candidates, the prompt still forbids the rest
  const stock = String(o.stock || '').toLowerCase().split(',').map(function (s) { return s.trim(); }).filter(Boolean);
  p = p.map(function (r) {
    const noms = r.ingredients.map(function (i) { return String(i.nom).toLowerCase(); });
    const utilise = stock.filter(function (s) { return noms.some(function (n) { return n.indexOf(s) !== -1 || s.indexOf(n) !== -1; }); });
    return Object.assign({}, r, { utilise: utilise });
  });
  if (o.frigo) p.sort(function (a, b) { return b.utilise.length - a.utilise.length; });
  return p.slice(0, 30);
}

// ---- Shared: leftovers logic ----
const JOURS_ORDRE = ['Lun', 'Mar', 'Mer', 'Jeu', 'Ven', 'Sam', 'Dim'];
function diner_veille(c) { const p = c.split('_'); const i = JOURS_ORDRE.indexOf(p[0]); return i > 0 ? JOURS_ORDRE[i - 1] + '_soir' : null; }
function dejeuner_lendemain(c) { const p = c.split('_'); const i = JOURS_ORDRE.indexOf(p[0]); return i >= 0 && i < 6 ? JOURS_ORDRE[i + 1] + '_midi' : null; }
function estReste(c, restes, tous) { return !!restes && /_midi$/.test(c) && tous.indexOf(diner_veille(c)) !== -1; }
function nourritReste(c, restes, tous) { return !!restes && /_soir$/.test(c) && tous.indexOf(dejeuner_lendemain(c)) !== -1; }

// Parses the Groq answer, re-attaches recipe data, doubles dinners that feed
// tomorrow's lunch, and writes leftover lunches as copies of that dinner.
const rep = $input.first().json;
function echec(raison) { return [{ json: { echec: true, raison: raison, recordId: ctx.recordId } }]; }
if (rep.error) return echec('Groq : ' + (rep.error.message || JSON.stringify(rep.error)).slice(0, 200));

let proposes = [];
if (ctx.cuisson.length) {
  const choix = (rep.choices || [])[0];
  if (!choix || !choix.message) return echec("Groq n'a pas renvoyé de réponse");
  if (choix.finish_reason === 'length') return echec('Réponse tronquée (max_tokens)');
  try {
    const sortie = JSON.parse(String(choix.message.content || '').replace(/```json|```/g, '').trim());
    proposes = Array.isArray(sortie.repas) ? sortie.repas : [];
  } catch (e) { return echec('JSON invalide renvoyé par Groq'); }
}

const FR = ctx.lang === 'fr';
const JOURS = FR ? { Lun: 'lundi', Mar: 'mardi', Mer: 'mercredi', Jeu: 'jeudi', Ven: 'vendredi', Sam: 'samedi', Dim: 'dimanche' }
                 : { Lun: 'Monday', Mar: 'Tuesday', Mer: 'Wednesday', Jeu: 'Thursday', Ven: 'Friday', Sam: 'Saturday', Dim: 'Sunday' };
const TXT = FR
  ? { ajout: 'Ajouté pour compléter ta semaine.', double: ' Préparé en double pour le déjeuner du lendemain.', reste: function (j) { return 'Restes du dîner de ' + j + '.'; } }
  : { ajout: 'Added to complete your week.', double: " Cooked in double for tomorrow's lunch.", reste: function (j) { return 'Leftovers from ' + j + ' dinner.'; } };

const parId = {}; ctx.pool.forEach(function (r) { parId[String(r.id)] = r; });
const parCreneau = {}; proposes.forEach(function (m) { if (m && m.creneau) parCreneau[String(m.creneau).trim()] = m; });
const utilises = {};
const cuisines = {};

function ligne(creneau, src, titre, pourquoi, cout, ingredients, temps) {
  const parts = creneau.split('_');
  return {
    "Identifiant": ctx.reference + '_' + creneau, "Creneau": creneau, "Jour": parts[0] || '', "Moment": parts[1] || '',
    "Plat": titre || src.titre, "Spoonacular ID": src.id, "Lien recette": src.lien || '', "Pourquoi ce plat": pourquoi || '',
    "Ingredients": JSON.stringify(ingredients), "Cout estime": Math.round((Number(cout) || 0) * 100) / 100,
    "Calories": src.calories || 0, "Proteines": src.proteines || 0, "Temps": temps || 0,
    "Statut": "propose", "Run": ctx.run, "Demande": ctx.reference
  };
}

ctx.cuisson.forEach(function (creneau) {
  const m = parCreneau[creneau] || {};
  let src = parId[String(m.recette_id)];
  let pourquoi = m.pourquoi, titre = FR ? m.titre : null;
  if (!src || utilises[src.id]) {
    src = ctx.pool.find(function (r) { return !utilises[r.id]; });
    // Pool exhausted: better an empty slot the user can fill than the same dish twice.
    if (!src) return;
    pourquoi = TXT.ajout; titre = null;
  }
  utilises[src.id] = true;
  const double = nourritReste(creneau, ctx.restes, ctx.creneauxDemande);
  const f = double ? 2 : 1;
  const ing = (src.ingredients || []).map(function (i) { return { nom: i.nom, quantite: Math.round(i.quantite * f * 100) / 100, unite: i.unite }; });
  cuisines[creneau] = ligne(creneau, src, titre, double ? (pourquoi || '') + TXT.double : pourquoi, (Number(m.cout_estime) || 0) * f, ing, src.temps_min);
});

const restesLignes = [];
ctx.aRemplir.filter(function (c) { return estReste(c, ctx.restes, ctx.creneauxDemande); }).forEach(function (c) {
  const d = diner_veille(c);
  const n = cuisines[d];
  const src = n ? { id: n["Spoonacular ID"], titre: n.Plat, lien: n["Lien recette"], calories: n.Calories, proteines: n.Proteines } : ctx.dinersGardes[d];
  if (!src) return;
  restesLignes.push(ligne(c, src, null, TXT.reste(JOURS[d.split('_')[0]]), 0, [], 0));
});

const tout = Object.keys(cuisines).map(function (k) { return cuisines[k]; }).concat(restesLignes);
if (tout.length === 0) return echec('Aucun repas proposé');
return tout.map(function (j) { return { json: j }; });

// Valide le payload reçu du site et construit la ligne Airtable.
// Email is now optional. Extra preferences (allergies, foods to avoid, cooking time,
// typed cuisines) travel inside "Payload brut", so no new Airtable columns are needed.

const body = $input.first().json.body || {};
const erreurs = [];

const email = (body.email || '').trim();
if (email && !email.includes('@')) {
  erreurs.push("Adresse email invalide");
}

const creneaux = Array.isArray(body.meal_slots) ? body.meal_slots : [];
if (creneaux.length === 0) {
  erreurs.push("Aucun créneau repas sélectionné");
}

const budget = Number(body.budget);
if (!budget || budget <= 0) {
  erreurs.push("Budget manquant ou invalide");
}

if (erreurs.length > 0) {
  return [{ json: { erreurs: erreurs } }];
}

const maintenant = new Date();
const y = maintenant.getFullYear();
const m = String(maintenant.getMonth() + 1).padStart(2, '0');
const d = String(maintenant.getDate()).padStart(2, '0');
const suffixe = Math.random().toString(36).slice(2, 7).toUpperCase();
const reference = `MP-${y}${m}${d}-${suffixe}`;

return [{
  json: {
    "Reference": reference,
    "Email": email,
    "Budget": budget,
    "Personnes": Number(body.people) || 1,
    "Regime": body.diet || 'aucun',
    "Cuisines": Array.isArray(body.cuisines) ? body.cuisines : [],
    "Notes": body.notes || '',
    "Stock": Array.isArray(body.stock) ? body.stock.join(', ') : '',
    "Creneaux": creneaux.join(', '),
    "Nb creneaux": creneaux.length,
    "Statut": "recue",
    "Payload brut": JSON.stringify(body, null, 2),
    "Cree le": maintenant.toISOString()
  }
}];
